"""Actual offline inference over visibly synthetic text; no credentials or API."""
import base64,json,time
from services.ocr_engine.ocr_core import run_local_ocr
IMAGE=''
if __name__=='__main__':
    start=time.monotonic();result=run_local_ocr(base64.b64decode(IMAGE),'business_license')
    assert '离线测试商户' in result['fields'].get('company_name',{}).get('value',''), 'REAL_OCR_SMOKE_NAME_NOT_READ'
    assert result['authenticity_verified'] is False and result['requires_human_confirmation'] is True
    print(json.dumps({'status':'REAL_OFFLINE_OCR_PASS','sample':'SYNTHETIC_TEXT_NOT_CREDENTIAL','field_keys':sorted(result['fields']),'seconds':round(time.monotonic()-start,3),'authenticity_verified':False}))
